"""One editable workspace shared by owner controls and the setup assistant."""
from __future__ import annotations

import hashlib
import re
from pathlib import Path

from jinja2 import DictLoader, Environment

from aicl.web.pages import TEMPLATES as BASE_TEMPLATES

TEMPLATE = """{% extends 'base' %}{% set page_key = 'workspace' %}
{% block eyebrow %}Your agent workspace{% endblock %}
{% block subtitle %}Shape the work, set its boundaries, and follow the results in one place.{% endblock %}
{% block header_actions %}<a class="button ghost" href="/work?workspace_id={{ state.id }}">Review work</a><a class="button ghost" href="/workspace">All agents</a><button type="button" class="secondary" id="workspace-assistant-toggle" aria-expanded="true" aria-controls="workspace-assistant">Hide assistant</button>{% endblock %}
{% block body %}
<link rel="stylesheet" href="{{ workspace_assets.css }}"><link rel="stylesheet" href="{{ workspace_assets.action_css }}">
<div class="agent-workspace" data-agent-workspace data-workspace-id="{{ state.id }}" data-csrf="{{ csrf }}">
  <p class="notice error" role="alert" data-workspace-error{% if not error %} hidden{% endif %}>{{ error }}</p>
  <p class="notice info" role="status" aria-live="polite" data-workspace-notice{% if not notice %} hidden{% endif %}>{{ notice }}</p>
  <noscript><p class="notice info">Enable JavaScript to edit this shared workspace and start work. Your saved settings are shown below.</p></noscript>
  <div class="notice info workspace-conflict" data-workspace-conflict hidden role="alert"><strong>This workspace changed while you were editing.</strong><p>Your edits are still here. Load the latest settings, or reapply your edits to the latest version.</p><div class="workspace-actions"><button type="button" class="secondary" data-conflict-load>Load latest settings</button><button type="button" class="secondary" data-conflict-reapply>Reapply my edits</button></div></div>
  <div class="notice info" data-external-conflict hidden role="alert"><strong>Saved agent settings changed elsewhere.</strong><p>Reload saved settings to continue. This discards this workspace’s draft changes and replaces them with the saved agent settings.</p><button type="button" class="secondary" data-command="reload">Reload saved settings</button></div>
  <div class="workspace-layout">
    <div class="workspace-main">
      <nav class="workspace-section-nav" aria-label="Agent sections"><a href="#workspace-goal">Goal</a><a href="#workspace-deliverables">Deliverables</a><a href="#workspace-tools">Permissions</a><a href="#workspace-schedule">Schedule</a><a href="#workspace-limits">Limits</a><a href="#workspace-funding">Funding</a><a href="#workspace-progress">Progress</a><a href="#workspace-results">Results</a></nav>
      <form id="workspace-draft-form">
        <section class="card workspace-section" id="workspace-goal" tabindex="-1"><div class="card-header"><div><p class="kicker">The work</p><h2>What should this agent achieve?</h2></div><span class="status-badge draft" data-draft-status>{{ 'Unapplied changes' if state.dirty else 'Settings applied' if state.published else 'Draft' }}</span></div><div class="card-body"><div class="field"><label for="workspace-name">Agent name</label><input id="workspace-name" name="name" value="{{ draft.name }}" maxlength="80" placeholder="e.g. Morning AI report"></div><div class="field"><label for="workspace-goal-input">Goal</label><textarea id="workspace-goal-input" name="goal" rows="3" maxlength="2000" placeholder="Describe the outcome you want.">{{ draft.goal }}</textarea></div><div class="field"><label for="workspace-inputs">Context and inputs</label><textarea id="workspace-inputs" name="inputs" rows="3" maxlength="4000" placeholder="Audience, source links, background, or other useful details.">{{ draft.inputs }}</textarea></div></div></section>
        <section class="card workspace-section" id="workspace-deliverables" tabindex="-1"><div class="card-header"><div><h2>Deliverables</h2><p class="muted">Define what good work looks like.</p></div><button type="button" class="secondary" data-add-deliverable>Add deliverable</button></div><div class="card-body" data-deliverables>{% for d in draft.deliverables %}<div class="workspace-deliverable" data-deliverable data-key="{{ d.key }}"><div class="field"><label for="deliverable-name-{{ loop.index }}">Name</label><input id="deliverable-name-{{ loop.index }}" data-deliverable-name value="{{ d.name }}" maxlength="120"></div><div class="field"><label for="deliverable-description-{{ loop.index }}">Description</label><textarea id="deliverable-description-{{ loop.index }}" data-deliverable-description rows="2" maxlength="2000">{{ d.description }}</textarea></div><div class="field"><label for="deliverable-criteria-{{ loop.index }}">Completion criteria · one per line</label><textarea id="deliverable-criteria-{{ loop.index }}" data-deliverable-criteria rows="3">{{ d.criteria|join('\n') }}</textarea></div><button type="button" class="ghost" data-remove-deliverable>Remove deliverable</button></div>{% endfor %}</div></section>
        <section class="card workspace-section" id="workspace-tools" tabindex="-1"><div class="card-header"><div><h2>Permissions</h2><p class="muted">Choose an access level for each feature, then apply settings.</p></div></div><div class="card-body">
          <div class="workspace-permission-matrix" data-permission-matrix>
            <div class="workspace-permission-header"><span>Feature</span><div class="workspace-permission-scale"><span>More restrictive</span><span aria-hidden="true">→</span><span>Less restrictive</span></div></div>
            {% for key,label,subtitle,policy,suffix in [('web_search','Web search','Brave Search',web_search,'search'),('web_access','Web access','Read public pages',web_access,'web')] %}
            <div class="workspace-permission-row" data-permission-row="{{ key }}"><div class="workspace-permission-feature"><strong>{{ label }}</strong><small>{{ subtitle }}</small></div><div class="workspace-permission-options" role="radiogroup" aria-label="{{ label }}" aria-describedby="workspace-{{ suffix }}-access-hint">{% for value,choice in [('off','Off'),('allowlist','Only selected sites'),('blocklist','All except selected sites'),('all','All public sites')] %}<label class="workspace-permission-option"><input type="radio" name="{{ key }}_mode" value="{{ value }}"{% if not legacy_web_access and policy.mode == value %} checked{% endif %}><span>{{ choice }}</span></label>{% endfor %}</div>
              <div class="workspace-web-details">
                <p class="field-hint" id="workspace-{{ suffix }}-access-hint" data-{{ suffix }}-access-hint>{{ 'Search is off.' if key == 'web_search' else 'Page reading is off.' }}</p>
                <p class="field-hint" data-legacy-{{ suffix }}{% if not legacy_web_access %} hidden{% endif %}>{{ 'Previous approval' if research_release.get('legacy') else 'Previous settings' }} — choose a level</p>
                <div class="field" data-{{ suffix }}-domains{% if policy.mode not in ['allowlist','blocklist'] %} hidden{% endif %}><label for="workspace-{{ suffix }}-domains" data-{{ suffix }}-domains-label>{{ ('Blocked search sites' if policy.mode == 'blocklist' else 'Allowed search sites') if key == 'web_search' else ('Blocked sites' if policy.mode == 'blocklist' else 'Allowed sites') }}</label><textarea id="workspace-{{ suffix }}-domains" name="{{ key }}_domains" rows="2" placeholder="example.com&#10;another-site.org" aria-describedby="workspace-{{ suffix }}-domains-hint">{{ policy.domains|join('\n') }}</textarea><p class="field-hint" id="workspace-{{ suffix }}-domains-hint">One domain per line. Each includes its subdomains.</p></div>
                {% if key == 'web_search' %}<details class="workspace-search-protection"><summary>How search is protected</summary><p>Brave receives search queries and site rules over HTTPS. AICL checks each request against your permissions and spending limits. Private context, files, and conversation stay out of web research. Results cannot change permissions.</p><p>Brave reports SOC 2 Type II attestation. Brave may retain API queries for up to 90 days; zero retention depends on the provider plan. <a href="https://api-dashboard.search.brave.com/documentation/resources/security" target="_blank" rel="noopener noreferrer">Brave security</a> · <a href="https://api-dashboard.search.brave.com/app/documentation/general/privacy-policy" target="_blank" rel="noopener noreferrer">API privacy</a></p></details>{% endif %}
              </div>
            </div>
            {% endfor %}
            <div data-other-capabilities hidden><div data-capabilities></div></div>
            {% for name,label,level in [('gmail.read','Read Gmail','Allow'),('gmail.send','Send Gmail','Ask each time'),('reddit.read','Read Reddit','Allow'),('reddit.post','Post to Reddit','Ask each time')] %}<div class="workspace-permission-row unavailable" data-permission-row="{{ name }}"><div class="workspace-permission-feature"><strong>{{ label }}</strong><small>Not yet available</small></div><div class="workspace-permission-options" role="radiogroup" aria-label="{{ label }}" aria-disabled="true">{% for value,choice in [('off','Off'),('allow',level)] %}<label class="workspace-permission-option"><input type="radio" name="unavailable-{{ name }}" value="{{ value }}" data-unavailable-capability="{{ name }}" disabled{% if value == 'off' %} checked{% endif %}><span>{{ choice }}</span></label>{% endfor %}</div></div>{% endfor %}
          </div>
          <p class="notice info" data-research-legacy{% if not research_release.get('legacy') %} hidden{% endif %}>This agent has an earlier web permission. It stays limited to that approval until you choose access levels and apply these settings.</p>
          <p class="notice info" data-research-availability{% if research_release.get('available') or (web_access.mode == 'off' and web_search.mode == 'off') %} hidden{% endif %}>{{ research_release.get('availability_message', 'Web research is unavailable. Connect a search service before enabling it.') }}</p>
          <div class="workspace-web-disclosure" data-web-disclosure{% if web_access.mode == 'off' and web_search.mode == 'off' %} hidden{% endif %}><p class="field-hint">Web research uses your <strong>Goal</strong> and site rules. Context, files, and conversation are excluded from web research. Keep sensitive details out of the goal when search or page reading is on.</p><p class="field-hint" data-research-recipient>{{ research_release.get('recipient_label', '') }}</p><p class="field-hint" data-research-status>Save your draft to review web research.</p><label class="workspace-capability" data-research-approval{% if not research_release.get('approval_required') %} hidden{% endif %}><input type="checkbox" id="workspace-research-approve" data-research-approve><span><strong>Allow web research for this goal</strong><small>I approve sharing the goal and site rules for research within the access levels above. Changes to the goal or either access level require my review.</small></span></label></div>
        </div></section>
        <section class="card workspace-section" id="workspace-schedule" tabindex="-1"><div class="card-header"><h2>Schedule</h2><span class="status-badge draft" data-schedule-status>Paused</span></div><div class="card-body"><div class="workspace-fields"><div class="field"><label for="workspace-cadence">Run frequency</label><select id="workspace-cadence" name="cadence">{% for value, label in [('manual','On demand'),('hourly','Hourly'),('daily','Daily')] %}<option value="{{ value }}"{% if draft.cadence == value %} selected{% endif %}>{{ label }}</option>{% endfor %}</select></div><div class="field"><label for="workspace-timezone">Timezone</label><input id="workspace-timezone" name="timezone" value="{{ draft.timezone }}" placeholder="America/New_York" maxlength="80"></div><div class="field" data-time-field><label for="workspace-time">Time</label><input id="workspace-time" name="time_of_day" type="time" value="{{ draft.time_of_day }}"></div></div><p class="field-hint" data-schedule-detail>Apply your settings before enabling a schedule.</p><button type="button" class="secondary" data-command="schedule" disabled>Enable schedule</button></div></section>
        <section class="card workspace-section" id="workspace-limits" tabindex="-1"><div class="card-header"><div><h2>Spending limits</h2><p class="muted">Maximum USD usage. Funding is separate from these limits.</p></div></div><div class="card-body workspace-fields">{% for key,label in limit_fields %}<div class="field"><label for="limit-{{ key }}">{{ label }}</label><div class="workspace-money"><span aria-hidden="true">$</span><input id="limit-{{ key }}" name="{{ key }}" data-limit type="number" min="0" step="0.000001" value="{{ '%.6f'|format(draft.limits.get(key,0)/1000000) }}"></div></div>{% endfor %}</div></section>
        <div class="workspace-save-bar"><p class="field-hint" role="status" data-save-status>{{ 'Review and apply the settings above to prepare this agent.' if state.dirty or not state.published else 'Apply settings to restore agent processing.' if state.get('inference_grant_missing') else 'Your settings are applied.' }}</p><div class="workspace-actions"><button type="submit" class="secondary" data-save-draft>Save draft</button><button type="button" class="primary" data-command="apply">Apply settings</button></div><p class="field-hint workspace-apply-note">Apply settings saves your permissions and spending limits. The assistant can propose changes; you approve them.</p></div>
      </form>
      <section class="card workspace-section" id="workspace-funding" tabindex="-1"><div class="card-header"><div><h2>Funding and readiness</h2><p class="muted">Prepare this agent before starting work.</p></div></div><div class="card-body"><div class="workspace-credit"><span>Service credit</span><span data-credit-before-setup>{{ money(readiness.get('credit_before_setup_micro_usd',readiness.get('balance_micro_usd',0))) }}</span></div><div class="workspace-credit"><span>Setup cost to settle</span><span data-setup-pending>{{ money(setup.pending_micro_usd) if setup else 'Unavailable' }}</span></div><div class="workspace-credit"><span>Setup cost paid</span><span data-setup-paid>{{ money(setup.charged_micro_usd) if setup else 'Unavailable' }}</span></div><div class="workspace-credit" data-setup-held-row{% if not setup or not setup.held_micro_usd %} hidden{% endif %}><span>Setup credit reserved</span><span data-setup-held>{{ money(setup.held_micro_usd) if setup else '' }}</span></div><div class="workspace-credit"><span>Available for work</span><strong data-credit-balance>{{ money(available_for_work) }}</strong></div><p class="field-hint" data-setup-shortfall{% if not setup_shortfall %} hidden{% endif %}>{% if setup_shortfall %}Add {{ money(setup_shortfall) }} in service credit to cover existing costs.{% endif %}</p><p class="field-hint" data-setup-status{% if not setup or not (setup.unknown or setup.busy) %} hidden{% endif %}>{% if setup and setup.unknown %}Some setup usage is still being confirmed.{% elif setup and setup.busy %}Setup is still in progress.{% endif %}</p><p class="field-hint" data-setup-hint>Setup cost is deducted from this agent’s service credit when you activate it or start work. Paid setup is already reflected in service credit.</p><p class="field-hint" data-credit-required></p><ul class="workspace-blockers" data-readiness-blockers>{% for b in readiness.get('blockers',[]) %}<li>{{ b.message }}</li>{% endfor %}</ul><p data-ready-message></p><div class="workspace-actions" data-lifecycle-controls hidden><span class="field-hint" data-lifecycle-status></span><button type="button" class="secondary" data-command="lifecycle" hidden>Resume agent</button></div><div class="workspace-fund-controls" data-fund-controls><div class="field"><label for="workspace-topup">Add service credit</label><select id="workspace-topup"><option value="500">$5.00</option><option value="1000">$10.00</option><option value="2000">$20.00</option></select></div><button type="button" class="primary" data-command="fund" disabled>Add funds with PayPal</button><p class="field-hint">Review and authorize payment in checkout, then return to this workspace.</p></div><a class="button primary" data-continue-payment hidden>Continue payment</a><p class="field-hint" data-funding-hint>Apply your settings to create the agent, then add funds here.</p></div></section>
      <section class="card workspace-section" id="workspace-progress" tabindex="-1"><div class="card-header"><div><p class="kicker">Agent work</p><h2>Progress</h2></div><span class="status-badge draft" data-run-status>Not started</span></div><div class="card-body"><p data-run-objective></p><p class="notice info" data-run-reason hidden></p><p class="field-hint" data-run-research hidden></p><ol class="workspace-plan" data-run-plan></ol><p class="muted" data-plan-empty>The agent will save its plan when work begins.</p><div class="workspace-actions workspace-run-controls"><button type="button" class="primary" data-command="start" disabled>Start work</button><button type="button" class="primary" data-command="resume" hidden>Continue work</button><button type="button" class="secondary" data-command="restart" hidden>Restart with updated settings</button><button type="button" class="secondary" data-command="pause" hidden>Pause work</button><button type="button" class="ghost" data-command="cancel" hidden>Cancel work</button><button type="button" class="ghost" data-refresh>Refresh progress</button></div><div class="notice info" data-run-settings hidden><p data-run-settings-message></p><p class="field-hint" data-run-tools></p><ul class="workspace-blockers" data-restart-blockers></ul></div><p class="field-hint" data-run-start-hint></p><p class="field-hint" data-poll-status role="status"></p><div class="workspace-run-question" data-run-question hidden><h3>The agent needs your input</h3><p data-question-text></p><div class="workspace-actions" data-question-options></div><p class="field-hint">Suggested replies fill the message box; they do not change tool access.</p></div><details data-run-guide hidden><summary>Guide this run</summary><ol class="workspace-run-messages" data-run-messages></ol><form id="workspace-run-message-form"><label for="workspace-run-message">Message to the worker</label><textarea id="workspace-run-message" rows="3" placeholder="Add context, a correction, or an answer."></textarea><p class="field-hint" data-run-message-hint>This message goes to the current run. Use the assistant to change agent settings.</p><button type="submit" class="secondary">Send to run</button></form></details></div></section>
      <section class="card workspace-section" id="workspace-results" tabindex="-1"><div class="card-header"><h2>Results</h2><a href="/work?workspace_id={{ state.id }}">Browse all runs</a></div><div class="card-body"><div data-run-artifacts><p class="muted">Completed results and saved drafts will appear here.</p></div><div data-run-activity></div></div></section>
    </div>
    <aside class="card workspace-assistant" id="workspace-assistant" aria-label="Workspace assistant"><div class="card-header"><div><p class="kicker">Working together</p><h2>Your assistant</h2><p class="muted">Talk through changes. See them in your settings.</p></div><span class="agent-avatar" aria-hidden="true">H</span></div><div class="workspace-transcript" data-transcript><ol data-management-messages aria-label="Conversation">{% for m in messages %}<li class="workspace-message {{ 'from-owner' if m.role == 'user' else 'from-assistant' }}"><strong>{{ 'You' if m.role == 'user' else 'Habitat status' if m.kind|default('') == 'recovery' else 'Habitat' }}</strong><div>{{ m.text }}</div></li>{% else %}<li class="workspace-welcome"><h3>What would you like to accomplish?</h3><p>I can help shape the goal, deliverables, schedule, and spending limits. You can edit every setting yourself, too.</p></li>{% endfor %}</ol></div><form id="workspace-assistant-form" class="workspace-composer"><label for="workspace-message">Talk to your assistant</label><textarea id="workspace-message" rows="3" placeholder="e.g. Prepare a daily report at 9 a.m. Eastern" required></textarea><div class="workspace-composer-actions"><p class="field-hint">Your assistant stays here throughout the work.</p><button type="submit" class="primary">Send ↑</button></div><p class="field-hint" role="status" data-assistant-status></p></form><p class="workspace-usage field-hint" data-assistant-usage>{% if scoped_usage %}Setup cost: {{ money(scoped_usage.spent_micro_usd) }} for this agent.{% if scoped_usage.unknown %} Some setup usage is still being confirmed.{% elif scoped_usage.busy %} Setup is still in progress.{% endif %}{% else %}Setup cost unavailable for this agent.{% endif %}</p></aside>
  </div>
  <script type="application/json" id="agent-workspace-data">{{ bootstrap|tojson }}</script>
</div><script src="{{ workspace_assets.markdown }}" defer></script><script src="{{ workspace_assets.action_js }}" defer></script><script src="{{ workspace_assets.js }}" defer></script>
{% endblock %}"""

STATIC_DIR = Path(__file__).parent.parent / "web" / "static"


ENV = Environment(loader=DictLoader({**BASE_TEMPLATES, "agent_workspace": TEMPLATE}), autoescape=True)
TOOL_TITLES = {"web.search": "Public web search", "web.read": "Read approved websites"}
LIMIT_FIELDS = (("inference_daily_micro_usd", "Inference · daily"), ("inference_monthly_micro_usd", "Inference · monthly"), ("compute_daily_micro_usd", "Compute · daily"), ("compute_monthly_micro_usd", "Compute · monthly"))


def _asset_url(name: str) -> str:
    """Change the browser cache key whenever the served asset content changes."""
    digest = hashlib.sha256((STATIC_DIR / name).read_bytes()).hexdigest()[:16]
    return f"/static/{name}?v={digest}"


def _money(value):
    amount = int(value or 0)
    return ("-$" if amount < 0 else "$") + re.sub(r"0{1,4}$", "", f"{abs(amount) / 1000000:.6f}")


def render_workspace(state: dict, *, csrf: str, account_name: str, messages: list, usage: dict | None, error: str = "", notice: str = "") -> str:
    """Render persisted state; all model/owner content is autoescaped or JSON escaped."""
    readiness = state.get("execution", {}).get("readiness", {})
    scoped = lambda value: value if isinstance(value, dict) and value.get("scope") == "workspace" and value.get("workspace_id") == state["id"] else None
    return ENV.get_template("agent_workspace").render(
        workspace_assets={**{ext: _asset_url(f"agent-workspace.{ext}") for ext in ("js", "css")}, "markdown": _asset_url("workspace-markdown.js"), "action_css": _asset_url("action-details.css"), "action_js": _asset_url("action-details.js")},
        state=state, draft=state["draft"], readiness=readiness, setup=scoped(readiness.get("setup")),
        web_access=state["draft"].get("web_access") or {"mode": "off", "domains": []},
        web_search=state["draft"].get("web_search") or state["draft"].get("web_access") or {"mode": "off", "domains": []},
        research_release=state.get("public_research_release", {}),
        legacy_web_access=state["draft"].get("web_access") is None and state["draft"].get("web_search") is None and (state.get("public_research_release", {}).get("legacy") or any(tool in {"web.read", "web.search", "web_search"} for tool in state["draft"].get("tools", []))),
        scoped_usage=scoped(usage), money=_money,
        tool_title=lambda capability: capability.get("title") or TOOL_TITLES.get(capability["name"], capability["name"]),
        available_for_work=max(0, readiness.get("balance_micro_usd", 0)),
        setup_shortfall=max(0, -readiness.get("balance_micro_usd", 0)),
        title=state["draft"].get("name") or "New agent", csrf=csrf, account_name=account_name,
        messages=messages, usage=usage, error=error, notice=notice, limit_fields=LIMIT_FIELDS, unified_workspace=True,
        bootstrap={"state": state, "messages": messages, "usage": usage},
    )
